{"code":"import subprocess, os

def env_dict(path):
    d = {}
    for line in open(path):
        line = line.strip()
        if not line or line.startswith('#') or '=' not in line: continue
        k, v = line.split('=', 1)
        d[k.strip()] = v.strip().strip('"\'')
    return d

backup = env_dict('/tmp/hermes-restore/.env')
live = env_dict('/data/.hermes/.env')

print("Keys in backup:", sorted(backup.keys()))
print("Keys in live:  ", sorted(live.keys()))
print()
for k, bv in sorted(backup.items()):
    if k not in live:
        print(f"{k}: MISSING in live -> will ADD")
    elif live[k] == bv:
        print(f"{k}: identical")
    else:
        # show masked comparison
        def mask(v): return v[:6] + "..." + v[-4:] if len(v) > 12 else "***"
        print(f"{k}: DIFFERENT | backup={mask(bv)} live={mask(live[k])}")
for k in live:
    if k not in backup:
        print(f"{k}: only in live (keeping)")
